9	func convertMotionMediaFromStore(motion *storepb.MotionMedia) *v1pb.MotionMedia {
10		if motion == nil {
11			return nil
12		}
13	
14		return &v1pb.MotionMedia{
15			Family:                  v1pb.MotionMediaFamily(motion.Family),
16			Role:                    v1pb.MotionMediaRole(motion.Role),
17			GroupId:                 motion.GroupId,
18			PresentationTimestampUs: motion.PresentationTimestampUs,
19			HasEmbeddedVideo:        motion.HasEmbeddedVideo,
20		}
21	}
22	
23	func convertMotionMediaToStore(motion *v1pb.MotionMedia) *storepb.MotionMedia {
24		if motion == nil {
25			return nil
26		}
27	
28		return &storepb.MotionMedia{
29			Family:                  storepb.MotionMediaFamily(motion.Family),
30			Role:                    storepb.MotionMediaRole(motion.Role),
31			GroupId:                 motion.GroupId,
32			PresentationTimestampUs: motion.PresentationTimestampUs,
33			HasEmbeddedVideo:        motion.HasEmbeddedVideo,
34		}
35	}
36	
37	func getAttachmentMotionMedia(attachment *store.Attachment) *storepb.MotionMedia {
38		if attachment == nil || attachment.Payload == nil {
39			return nil
40		}
41		return attachment.Payload.MotionMedia
42	}
43	
44	func isAndroidMotionContainer(motion *storepb.MotionMedia) bool {
45		return motion != nil &&
46			motion.Family == storepb.MotionMediaFamily_ANDROID_MOTION_PHOTO &&
47			motion.Role == storepb.MotionMediaRole_CONTAINER &&
48			motion.HasEmbeddedVideo
49	}
50	
51	func ensureAttachmentPayload(payload *storepb.AttachmentPayload) *storepb.AttachmentPayload {
52		if payload != nil {
53			return payload
54		}
55		return &storepb.AttachmentPayload{}
56	}
57	
58	func isMultiMemberMotionGroup(attachments []*store.Attachment) bool {
59		if len(attachments) < 2 {
60			return false
61		}
62		for _, attachment := range attachments {
63			motion := getAttachmentMotionMedia(attachment)
64			if motion == nil || motion.GroupId == "" {
65				return false
66			}
67		}
68		return true
69	}
